import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"解","description":"周易集解 - 解","frontmatter":{"title":"解","description":"周易集解 - 解"},"headers":[],"relativePath":"classics/jijie/040.md","filePath":"classics/jijie/040.md"}'),l={name:"classics/jijie/040.md"};function n(d,a,p,t,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="解" tabindex="-1">解 <a class="header-anchor" href="#解" aria-label="Permalink to “解”">​</a></h1><h2 id="解-1" tabindex="-1">解 <a class="header-anchor" href="#解-1" aria-label="Permalink to “解”">​</a></h2><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>解，利西南，無所往，其來複吉。有攸往，夙吉。</p><h2 id="卦辭注" tabindex="-1">卦辭注 <a class="header-anchor" href="#卦辭注" aria-label="Permalink to “卦辭注”">​</a></h2><p>《序卦》曰：物不可以終難，故受之以解。解者，緩也。</p><p>崔憬曰：蹇終則來碩吉，利見大人，故言物不可以終難。故受之以解。</p><p>虞翻曰：臨初之四。坤，西南卦。初之四，得坤眾。故｢利西南，往得眾也｣。</p><p>虞翻曰：謂四本從初之四，失位於外，而無所應，宜來反初，故無所往。復得正位，故其來複吉也。二往之五，四來之初，成屯，體復象，故稱來複吉矣。</p><p>虞翻曰：謂二也。夙，早也。離為日，為甲。日出甲上，故早也。九二失正，早往之五，則吉。故｢有攸往，夙吉，往有功也｣。</p><h2 id="彖" tabindex="-1">彖 <a class="header-anchor" href="#彖" aria-label="Permalink to “彖”">​</a></h2><p>《彖》曰：解，險以動，動而免乎險，解。解，利西南，往得眾也。無所往，其來複吉，乃得中也。有攸往，夙吉，往有功也。天地解而雷雨作，雷雨作而百果草木皆甲坼。解之時大矣哉。</p><h2 id="彖傳注" tabindex="-1">彖傳注 <a class="header-anchor" href="#彖傳注" aria-label="Permalink to “彖傳注”">​</a></h2><p>虞翻曰：險，坎。動，震。解，二月。雷以動之，雨以潤之，物鹹孚甲，萬物生震。震出險上，故免乎險也。</p><p>荀爽曰：乾動之坤而得眾，西南，眾之象也。</p><p>荀爽曰：陰處尊位，陽無所往也。</p><p>荀爽曰：來複居二，處中成險，故曰復吉也。</p><p>荀爽曰：五位無君，二陽又卑，往居之者則吉。據五解難，故有功也。</p><p>荀爽曰：謂乾坤交通，動而成解卦，坎下震上，故雷雨作也。</p><p>荀爽曰：解者，震世也。仲春之月，草木萌牙。雷以動之，雨以潤之，日以烜之，故甲坼也。</p><p>王弼曰：無所而不釋也。難解之時，非治難時也。故不言用也。體盡於解之名，無有幽隱，故不曰義也。</p><h2 id="象" tabindex="-1">象 <a class="header-anchor" href="#象" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：雷雨作，解。君子以赦過宥罪。</p><h2 id="象傳注" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注" aria-label="Permalink to “象傳注”">​</a></h2><p>虞翻曰：君子謂三。伏陽出，成大過。坎為罪，入則大過象壞，故以赦過。二四失位，皆在坎獄中。三出體乾，兩坎不見。震喜兌悅，罪人皆出，故以宥罪。謂三入則赦過，出則宥罪。公用射隼以解悖，是其義也。</p><h2 id="初六" tabindex="-1">初六 <a class="header-anchor" href="#初六" aria-label="Permalink to “初六”">​</a></h2><p>初六，無咎。</p><h2 id="初六注" tabindex="-1">初六注 <a class="header-anchor" href="#初六注" aria-label="Permalink to “初六注”">​</a></h2><p>虞翻曰：與四易位，體震得正，故無咎也。</p><h2 id="象-1" tabindex="-1">象 <a class="header-anchor" href="#象-1" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：剛柔之際，義無咎也。</p><h2 id="象傳注-1" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-1" aria-label="Permalink to “象傳注”">​</a></h2><p>虞翻曰：體屯初震，剛柔始交，故無咎也。</p><h2 id="九二" tabindex="-1">九二 <a class="header-anchor" href="#九二" aria-label="Permalink to “九二”">​</a></h2><p>九二，田獲三狐，得黃矢，貞吉。</p><h2 id="九二注" tabindex="-1">九二注 <a class="header-anchor" href="#九二注" aria-label="Permalink to “九二注”">​</a></h2><p>虞翻曰：二稱田。田，獵也。變之正，艮為狐。坎為弓。離為黃矢，矢貫狐體。二之五，歷三爻。故｢田獲三狐，得黃矢｣。之正得中，故貞吉。</p><h2 id="象-2" tabindex="-1">象 <a class="header-anchor" href="#象-2" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：九二貞吉，得中道也。</p><h2 id="象傳注-2" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-2" aria-label="Permalink to “象傳注”">​</a></h2><p>虞翻曰：動得正，故得中道。</p><h2 id="六三" tabindex="-1">六三 <a class="header-anchor" href="#六三" aria-label="Permalink to “六三”">​</a></h2><p>六三，負且乘，致寇至，貞吝。</p><h2 id="六三注" tabindex="-1">六三注 <a class="header-anchor" href="#六三注" aria-label="Permalink to “六三注”">​</a></h2><p>虞翻曰：負，倍也。二變時艮為背，謂三以四艮倍五也。五來寇三時，坤為車，三在坤上，故負且乘。小人而乘君子之器，《象》曰｢亦可醜也｣。</p><p>虞翻曰：五之二成坎，坎為寇盜。上位慢五，下暴於二，慢藏誨盜，故｢致寇至，貞吝｣。《象》曰：｢自我致戎，又誰咎也。｣</p><h2 id="象-3" tabindex="-1">象 <a class="header-anchor" href="#象-3" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：負且乘，亦可醜也。自我致戎，又誰咎也。</p><h2 id="象傳注-3" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-3" aria-label="Permalink to “象傳注”">​</a></h2><p>虞翻曰：臨坤為醜也。坤為自我。以離兵伐三，故轉寇為戎。艮手招盜，故誰咎也。</p><h2 id="九四" tabindex="-1">九四 <a class="header-anchor" href="#九四" aria-label="Permalink to “九四”">​</a></h2><p>九四，解而拇，朋至斯孚。</p><h2 id="九四注" tabindex="-1">九四注 <a class="header-anchor" href="#九四注" aria-label="Permalink to “九四注”">​</a></h2><p>虞翻曰：二動時艮為指。四變之坤為拇，故解而拇。臨兌為朋，坎為孚。四陽從初，故朋至斯孚矣。</p><h2 id="象-4" tabindex="-1">象 <a class="header-anchor" href="#象-4" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：解而拇，未當位也。</p><h2 id="象傳注-4" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-4" aria-label="Permalink to “象傳注”">​</a></h2><p>王弼曰：失位不正，而比於三。故三得附之，為其拇也。三為之拇，則失初之應，故解其拇，然後朋至斯孚而信矣。</p><p>案：九四體震，震為足。三在足下，拇之象。</p><h2 id="六五" tabindex="-1">六五 <a class="header-anchor" href="#六五" aria-label="Permalink to “六五”">​</a></h2><p>六五，君子維有解，吉。有孚於小人。</p><h2 id="六五注" tabindex="-1">六五注 <a class="header-anchor" href="#六五注" aria-label="Permalink to “六五注”">​</a></h2><p>虞翻曰：君子謂二。之五得正成坎，坎為心。故｢君子維有解，吉｣。小人謂五。陰為小人，君子升位，則小人退在二，故有孚於小人。坎為孚也。</p><h2 id="象-5" tabindex="-1">象 <a class="header-anchor" href="#象-5" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：君子有解，小人退也。</p><h2 id="象傳注-5" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-5" aria-label="Permalink to “象傳注”">​</a></h2><p>虞翻曰：二陽上之五，五陰小人退之二也。</p><h2 id="上六" tabindex="-1">上六 <a class="header-anchor" href="#上六" aria-label="Permalink to “上六”">​</a></h2><p>上六，公用射隼於高墉之上，獲之，無不利。</p><h2 id="上六注" tabindex="-1">上六注 <a class="header-anchor" href="#上六注" aria-label="Permalink to “上六注”">​</a></h2><p>虞翻曰：上應在三。公，謂三伏陽也。離為隼。三失位，動出成乾，貫隼入大過，故｢公用射隼於高墉之上，獲之，無不利｣也。</p><p>案：二變時體艮。艮為山，為宮闕，三在山半，高墉之象也。</p><h2 id="象-6" tabindex="-1">象 <a class="header-anchor" href="#象-6" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：公用射隼，以解悖也。</p><h2 id="象傳注-6" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-6" aria-label="Permalink to “象傳注”">​</a></h2><p>虞翻曰：坎為悖，三出成乾，而坎象壞，故解悖也。</p><p>《九家易》曰：隼，鷙鳥也。今捕食雀者，其性疾害，喻暴君也。陰盜陽位，萬事悖亂，今射去之，故曰以解悖也。</p>',77)])])}const m=e(l,[["render",n]]);export{b as __pageData,m as default};
